/**
 * The admitted interface catalogue (DECISIONS.md #117), generated by `model/i18n.py admit` into
 * `assets/i18n/catalogue.json`: English, plus every language whose draft was reviewed by the other model and
 * read by a native speaker. Nothing else names a language; the agents' language drafts are never read
 * here (`tests/test_i18n_drafts.py` `NeverRendered`).
 *
 * Two lookups. `t(key)` is the app's own wording, by key. `tx(text)` is the content model's: a label or gap span,
 * a section title or the evidence disclaimer, matched by its exact English text, so a wording the model changes
 * falls back to English until it is drafted again. Facts, quotes and explanations are never looked up (#82).
 */
export interface Language {
  lang: string;
  /** The language's name in itself. */
  name: string;
  strings: Record<string, string>;
  /** Per state: the wording that state's admitted column uses where it differs from the language's. */
  overlays: Record<string, Record<string, string>>;
  provenance: Record<string, string>[];
}

export interface Catalogue {
  languages: Record<string, Language>;
  /** Each member state's official languages, the first being the one its report opens in. */
  states: Record<string, string[]>;
}

export type Vars = Record<string, string | number>;

export const CATALOGUE: Catalogue = require('../../assets/i18n/catalogue.json');

/** The keys whose English text the content model prints, and so may be matched by `tx`. */
const CONTENT = /^(label|gap|section)\.|^notice\.disclaimer$/;

export function fill(template: string, vars?: Vars): string {
  if (!vars) return template;
  return template.replace(/\{(\w+)\}/g, (whole, name: string) =>
    name in vars ? String(vars[name]) : whole
  );
}

export interface Translator {
  lang: string;
  /** The state whose admitted wording overrides the language's, if any. */
  region: string | null;
  t(key: string, vars?: Vars): string;
  tx(english: string): string;
}

export function translator(
  catalogue: Catalogue,
  lang: string,
  region: string | null = null
): Translator {
  const en = catalogue.languages.en?.strings ?? {};
  const chosen = catalogue.languages[lang] ?? catalogue.languages.en;
  const overlay = (region && chosen?.overlays[region]) || {};
  const word = (key: string): string | undefined => overlay[key] ?? chosen?.strings[key] ?? en[key];
  const byText = new Map<string, string>();
  for (const [key, text] of Object.entries(en))
    if (CONTENT.test(key) && !byText.has(text)) byText.set(text, key);
  return {
    lang: chosen?.lang ?? 'en',
    region: region && chosen?.overlays[region] ? region : null,
    t: (key, vars) => fill(word(key) ?? key, vars),
    tx: (english) => {
      const key = byText.get(english);
      return key ? (word(key) ?? english) : english;
    },
  };
}

export const english: Translator = translator(CATALOGUE, 'en');

export interface Locale {
  languageCode: string | null;
  regionCode: string | null;
}

/** The reader's choice if admitted, else the first device language that is, else English. */
export function pickLanguage(
  catalogue: Catalogue,
  chosen: { lang: string; region?: string | null } | null,
  device: Locale[]
): { lang: string; region: string | null } {
  if (chosen && catalogue.languages[chosen.lang])
    return { lang: chosen.lang, region: chosen.region ?? null };
  for (const l of device)
    if (l.languageCode && catalogue.languages[l.languageCode])
      return { lang: l.languageCode, region: l.regionCode };
  return { lang: 'en', region: null };
}

/** The language a state's report opens in, if it is admitted and is not English. */
export function stateLanguage(catalogue: Catalogue, iso: string): string | null {
  return (
    (catalogue.states[iso] ?? []).find((l) => l !== 'en' && catalogue.languages[l] !== undefined) ??
    null
  );
}
